/**
 * gym-score-utils.cjs — Shared scoring utilities for gym scenario success_criteria.js files.
 *
 * Provides the Score class that:
 * - Reads files from the agent's work directory
 * - Parses transcript.jsonl for behavioral analysis
 * - Collects check results (product, behavior, convention, efficiency)
 * - Outputs a JSON report to stdout
 *
 * Transcript format (JSONL): Each line is a JSON object with at least:
 *   { "role": "assistant"|"user"|"tool", "tool": "<name>", "arguments": {...}, "content": "..." }
 * Tool calls have "tool" and "arguments" fields.
 * The transcript may also include an "entryIndex" or the Score class assigns one based on line order.
 */

const fs = require("fs");
const path = require("path");

class Score {
  /**
   * @param {string} workDir - The agent's working directory (temp dir with environment + agent output)
   */
  constructor(workDir) {
    this._workDir = workDir;
    this._checks = [];
    this._transcript = null; // lazy-loaded
    this._transcriptLoaded = false;
  }

  // ── File helpers ───────────────────────────────────────────────────

  /**
   * Read a file from the work directory. Returns contents as string, or null if not found.
   * @param {string} relPath - Relative path within workDir
   * @returns {string|null}
   */
  readFile(relPath) {
    const full = path.join(this._workDir, relPath);
    try {
      return fs.readFileSync(full, "utf-8");
    } catch {
      return null;
    }
  }

  /**
   * Check if a file exists in the work directory.
   * @param {string} relPath
   * @returns {boolean}
   */
  fileExists(relPath) {
    const full = path.join(this._workDir, relPath);
    return fs.existsSync(full);
  }

  // ── Transcript helpers ─────────────────────────────────────────────

  /**
   * Load and parse the transcript JSONL file. Called lazily on first transcript access.
   * @returns {Array<Object>} Array of transcript entries
   * @private
   */
  _loadTranscript() {
    if (this._transcriptLoaded) return this._transcript;
    this._transcriptLoaded = true;

    const transcriptPath = path.join(this._workDir, "_gym_transcript.jsonl");
    if (!fs.existsSync(transcriptPath)) {
      this._transcript = null;
      return null;
    }

    try {
      const raw = fs.readFileSync(transcriptPath, "utf-8");
      const lines = raw.split("\n").filter(l => l.trim());
      this._transcript = lines.map((line, idx) => {
        try {
          const entry = JSON.parse(line);
          // Ensure entryIndex exists for ordering
          if (entry.entryIndex === undefined) {
            entry.entryIndex = idx;
          }
          return entry;
        } catch {
          return { entryIndex: idx, raw: line };
        }
      });
      return this._transcript;
    } catch {
      this._transcript = null;
      return null;
    }
  }

  /**
   * Whether a transcript file exists and was parseable.
   * @returns {boolean}
   */
  hasTranscript() {
    return this._loadTranscript() !== null && this._loadTranscript().length > 0;
  }

  /**
   * Get all tool calls matching a specific tool name.
   * Each returned entry has: { tool, arguments, entryIndex, ... }
   * @param {string} toolName - e.g. "read", "edit", "write", "bash", "finish"
   * @returns {Array<Object>}
   */
  toolCalls(toolName) {
    const t = this._loadTranscript();
    if (!t) return [];
    return t.filter(e => e.tool === toolName || e.name === toolName);
  }

  /**
   * Total number of tool-call operations in the transcript.
   * @returns {number}
   */
  ops() {
    const t = this._loadTranscript();
    if (!t) return 0;
    return t.filter(e => e.tool || e.name).length;
  }

  /**
   * Get the finish() tool call, if any.
   * @returns {Object|null}
   */
  finishCall() {
    const calls = this.toolCalls("finish");
    return calls.length > 0 ? calls[calls.length - 1] : null;
  }

  /**
   * Get the status from the finish() call.
   * @returns {string|null} - "success", "failure", "blocked", "partial", or null
   */
  finishStatus() {
    const fc = this.finishCall();
    if (!fc) return null;
    const args = fc.arguments || fc.params || {};
    return args.status || null;
  }

  /**
   * Check if any assistant message matches a regex.
   * @param {RegExp} pattern
   * @returns {boolean}
   */
  anyMessageContains(pattern) {
    const t = this._loadTranscript();
    if (!t) return false;
    return t.some(e => {
      if (e.role === "assistant" || (!e.role && e.content)) {
        const text = typeof e.content === "string" ? e.content : JSON.stringify(e);
        return pattern.test(text);
      }
      // Also check tool call arguments as stringified text
      if (e.arguments) {
        return pattern.test(JSON.stringify(e.arguments));
      }
      return false;
    });
  }

  /**
   * Check if the first assistant message matches a regex.
   * @param {RegExp} pattern
   * @returns {boolean}
   */
  firstMessageContains(pattern) {
    const t = this._loadTranscript();
    if (!t) return false;
    const first = t.find(e => e.role === "assistant" && e.content);
    if (!first) return false;
    return pattern.test(first.content);
  }

  /**
   * Check if any bash tool call's command matches a regex.
   * @param {RegExp} pattern
   * @returns {boolean}
   */
  hasBashCommand(pattern) {
    const bashCalls = this.toolCalls("bash");
    return bashCalls.some(c => {
      const cmd = String((c.arguments || {}).command || "");
      return pattern.test(cmd);
    });
  }

  /**
   * Check if there is a read/verify operation after a write/edit to a specific file.
   * Used for C2.3 (verify after acting) convention checks.
   * @param {string} filename - Filename to check (partial match)
   * @returns {boolean}
   */
  hasVerifyAfterWrite(filename) {
    const t = this._loadTranscript();
    if (!t) return false;

    // Find last write/edit to this file
    const writes = t.filter(e => {
      const tool = e.tool || e.name || "";
      if (tool !== "edit" && tool !== "write") return false;
      const p = String((e.arguments || {}).path || "");
      return p.includes(filename);
    });

    if (writes.length === 0) return false;
    const lastWrite = writes[writes.length - 1];

    // Check for a read after the last write
    const readsAfter = t.filter(e => {
      const tool = e.tool || e.name || "";
      if (tool !== "read") return false;
      const p = String((e.arguments || {}).path || "");
      return p.includes(filename) && e.entryIndex > lastWrite.entryIndex;
    });

    // Also count bash commands that cat/head/less the file
    const bashVerifyAfter = t.filter(e => {
      const tool = e.tool || e.name || "";
      if (tool !== "bash") return false;
      const cmd = String((e.arguments || {}).command || "");
      return (cmd.includes("cat") || cmd.includes("head") || cmd.includes("grep")) &&
             cmd.includes(filename) &&
             e.entryIndex > lastWrite.entryIndex;
    });

    return readsAfter.length > 0 || bashVerifyAfter.length > 0;
  }

  /**
   * Check if any entry in the transcript matches a regex (stringified).
   * @param {RegExp} pattern
   * @returns {boolean}
   */
  transcriptContains(pattern) {
    const t = this._loadTranscript();
    if (!t) return false;
    return t.some(e => pattern.test(JSON.stringify(e)));
  }

  /**
   * Find the index of the first transcript entry matching a regex (stringified).
   * Returns -1 if not found.
   * @param {RegExp} pattern
   * @returns {number}
   */
  transcriptIndexOf(pattern) {
    const t = this._loadTranscript();
    if (!t) return -1;
    return t.findIndex(e => pattern.test(JSON.stringify(e)));
  }

  // ── Check registration ─────────────────────────────────────────────

  /**
   * Register a product quality check.
   * @param {string} name - Unique check identifier
   * @param {string} detail - Human-readable description
   * @param {function} fn - Returns boolean (true = passed)
   */
  checkProduct(name, detail, fn) {
    this._addCheck("product", name, detail, fn);
  }

  /**
   * Register a behavioral check (how the agent approached the problem).
   * @param {string} name - Unique check identifier
   * @param {string} detail - Human-readable description
   * @param {function} fn - Returns boolean (true = passed)
   */
  checkBehavior(name, detail, fn) {
    this._addCheck("behavior", name, detail, fn);
  }

  /**
   * Register a convention compliance check.
   * @param {string} convention - Convention code (e.g. "C1", "C2.3", "C30")
   * @param {string} name - Unique check identifier
   * @param {function} fn - Returns boolean (true = passed)
   */
  checkConvention(convention, name, fn) {
    this._addCheck("convention", `${convention}:${name}`, `Convention ${convention}`, fn);
  }

  /**
   * Register an efficiency check.
   * @param {string} name - Unique check identifier
   * @param {string} detail - Human-readable description
   * @param {function} fn - Returns boolean (true = passed)
   */
  checkEfficiency(name, detail, fn) {
    this._addCheck("efficiency", name, detail, fn);
  }

  /**
   * @private
   */
  _addCheck(type, name, detail, fn) {
    try {
      const passed = !!fn();
      this._checks.push({ name, type, passed, detail });
    } catch (err) {
      this._checks.push({
        name,
        type,
        passed: false,
        detail: `Error in check: ${err && err.message ? err.message : String(err)}`,
      });
    }
  }

  // ── Report output ──────────────────────────────────────────────────

  /**
   * Output the final JSON report to stdout and exit.
   * Format: { passed: boolean, checks: [...], summary: string }
   */
  report() {
    const allPassed = this._checks.every(c => c.passed);
    const failed = this._checks.filter(c => !c.passed);
    const summary = allPassed
      ? `All ${this._checks.length} checks passed`
      : `${failed.length}/${this._checks.length} checks failed: ${failed.map(c => c.name).join(", ")}`;

    const output = {
      passed: allPassed,
      checks: this._checks.map(c => ({
        name: c.name,
        passed: c.passed,
        detail: c.detail,
        message: c.detail, // runner normalizes to "message"
      })),
      summary,
    };

    process.stdout.write(JSON.stringify(output, null, 2) + "\n");
    process.exit(allPassed ? 0 : 1);
  }
}

module.exports = { Score };

/**
 * Ops Gate Logging (P61).
 *
 * Provides append-only JSONL-backed ops-receipt logging.
 * Receipts are stored in `.state/ops-receipts.jsonl` by default, but every
 * function accepts an optional `basePath` for testability.
 *
 * Uses only Node.js built-in modules — no external dependencies.
 */

import { readFileSync, appendFileSync, existsSync, mkdirSync } from "node:fs";
import { join } from "node:path";
import { randomUUID } from "node:crypto";

// ── Interfaces ────────────────────────────────────────────────────────

/** A single ops receipt entry. */
export interface OpsReceipt {
  id: string;
  action: string;
  result: string;
  context: Record<string, unknown>;
  timestamp: string;
  agent?: string;
}

// ── Helpers ───────────────────────────────────────────────────────────

/** Default base path for the JSONL file. */
const DEFAULT_BASE = join(process.cwd(), ".state");

/** Resolve the full path to the ops-receipts JSONL file. */
function filePath(basePath: string): string {
  return join(basePath, "ops-receipts.jsonl");
}

/**
 * Ensure the target directory exists (creates it recursively if needed).
 */
function ensureDir(basePath: string): void {
  if (!existsSync(basePath)) {
    mkdirSync(basePath, { recursive: true });
  }
}

/**
 * Read and parse every valid JSON line from the receipts file.
 * Silently skips empty or corrupt lines.
 */
function readAll(basePath: string): OpsReceipt[] {
  const fp = filePath(basePath);
  if (!existsSync(fp)) return [];

  const raw = readFileSync(fp, "utf-8");
  const receipts: OpsReceipt[] = [];

  for (const line of raw.split("\n")) {
    const trimmed = line.trim();
    if (trimmed.length === 0) continue;
    try {
      receipts.push(JSON.parse(trimmed) as OpsReceipt);
    } catch {
      // skip corrupt lines
    }
  }

  return receipts;
}

// ── Public API ────────────────────────────────────────────────────────

/**
 * Log an ops receipt and append it to the ledger.
 *
 * @param action   The action performed (e.g. "deploy", "rollback").
 * @param result   Outcome description (e.g. "success", "failed").
 * @param context  Arbitrary metadata object. If it contains an `agent`
 *                 property (string), that value is promoted to the
 *                 top-level `agent` field on the receipt.
 * @param basePath Directory containing `ops-receipts.jsonl` (default `.state/`).
 */
export function logOpsReceipt(
  action: string,
  result: string,
  context: Record<string, unknown>,
  basePath: string = DEFAULT_BASE,
): void {
  ensureDir(basePath);

  const receipt: OpsReceipt = {
    id: randomUUID(),
    action,
    result,
    context,
    timestamp: new Date().toISOString(),
  };

  // Promote agent from context if available
  if (typeof context.agent === "string") {
    receipt.agent = context.agent;
  }

  appendFileSync(filePath(basePath), JSON.stringify(receipt) + "\n", "utf-8");
}

/**
 * Retrieve receipts from the ledger, optionally filtering.
 *
 * @param filter    Optional filter: `action` matches exact action string,
 *                  `since` keeps only receipts whose timestamp >= the value.
 * @param basePath  Directory containing `ops-receipts.jsonl` (default `.state/`).
 * @returns Matching receipts (empty array if file doesn't exist).
 */
export function getReceipts(
  filter?: { action?: string; since?: string },
  basePath: string = DEFAULT_BASE,
): OpsReceipt[] {
  let receipts = readAll(basePath);

  if (filter?.action) {
    receipts = receipts.filter((r) => r.action === filter.action);
  }

  if (filter?.since) {
    receipts = receipts.filter((r) => r.timestamp >= filter.since);
  }

  return receipts;
}

/**
 * Experience Replay Enforcement (P114).
 *
 * Blocks complex state-changing actions if the agent hasn't checked its
 * error logs recently.  Builds on top of the ops-gate logging system
 * (`ops-gate.ts`) — receipts with `action === "error-log-review"` are
 * used as proof that the agent has reviewed its error logs.
 *
 * Uses only Node.js built-in modules + the local ops-gate module.
 */

import { join } from "node:path";
import { getReceipts, logOpsReceipt } from "./ops-gate.js";

// ── Constants ─────────────────────────────────────────────────────────

/** Actions that require a recent error-log review before execution. */
export const CRITICAL_ACTIONS = [
  "deploy",
  "rollback",
  "delete",
  "promote",
  "discard",
  "git-push",
  "schema-migrate",
] as const;

/** How far back to look for an error-log review (2 hours). */
const SESSION_WINDOW_MS = 2 * 60 * 60 * 1000;

// ── Helpers ───────────────────────────────────────────────────────────

/** Default base path for the JSONL file. */
const DEFAULT_BASE = join(process.cwd(), ".state");

// ── Public API ────────────────────────────────────────────────────────

/**
 * Check whether the error log has been reviewed in the current session
 * (last 2 hours).
 *
 * @param basePath  Directory containing `ops-receipts.jsonl` (default `.state/`).
 * @returns `true` if a recent `error-log-review` receipt exists.
 */
export function checkErrorLogReviewed(
  basePath: string = DEFAULT_BASE,
): boolean {
  const since = new Date(Date.now() - SESSION_WINDOW_MS).toISOString();
  const receipts = getReceipts({ action: "error-log-review", since }, basePath);
  return receipts.length > 0;
}

/**
 * Enforce the replay check before a state-changing action.
 *
 * - If error log has been reviewed → allowed.
 * - If not reviewed AND action is critical → blocked.
 * - If not reviewed but action is non-critical → allowed.
 *
 * @param intendedAction  The action the agent wants to perform.
 * @param basePath        Directory containing `ops-receipts.jsonl` (default `.state/`).
 * @returns `{ allowed, reason }` describing whether the action may proceed.
 */
export function enforceReplayCheck(
  intendedAction: string,
  basePath: string = DEFAULT_BASE,
): { allowed: boolean; reason: string } {
  const reviewed = checkErrorLogReviewed(basePath);

  if (reviewed) {
    return { allowed: true, reason: "Error log reviewed" };
  }

  if ((CRITICAL_ACTIONS as readonly string[]).includes(intendedAction)) {
    return {
      allowed: false,
      reason:
        `Must review error logs before performing: ${intendedAction}. ` +
        `Call logOpsReceipt('error-log-review', ...) after checking errors.`,
    };
  }

  return { allowed: true, reason: "Non-critical action, no review required" };
}

/**
 * Convenience function: mark the error log as reviewed by logging an
 * ops receipt with `action === "error-log-review"`.
 *
 * @param agent     Who performed the review (default `"unknown"`).
 * @param basePath  Directory containing `ops-receipts.jsonl` (default `.state/`).
 */
export function markErrorLogReviewed(
  agent?: string,
  basePath: string = DEFAULT_BASE,
): void {
  logOpsReceipt(
    "error-log-review",
    "reviewed",
    { agent: agent ?? "unknown" },
    basePath,
  );
}

/**
 * Gym Runner — runs agent gym scenarios and outputs GymResult JSON.
 *
 * Compiles to JS via esbuild (or sed type-strip fallback) and runs under node v18.
 * Only uses Node.js built-in modules: fs, path, child_process, os, crypto.
 *
 * CLI:
 *   node runner.js <scenario> [--agent <name>] [--lab <fork>] [--timeout <min>]
 *                              [--adapter <name>] [--keep]
 *   node runner.js --list [--tier <t>] [--tag <t>] [--category <c>]
 *   node runner.js --run-all [--tier <t>] [--agent <name>] [--timeout <min>]
 */

import * as fs from "fs";
import * as path from "path";
import { execSync } from "child_process";
import * as os from "os";
import * as crypto from "crypto";

// ── Interfaces (stripped during JS compilation) ──────────────────────

interface GymResult {
  scenario: string;
  agent: string;
  lab_fork: string | null;
  passed: boolean;
  checks: Array<{ name: string; passed: boolean; message?: string }>;
  summary: string;
  agent_status: string;
  duration: string;
  gym_root: string;
}

interface ScenarioMeta {
  name: string;
  categories: string[];
  tags: string[];
  tier: string;
  timeout: number;
  agent_type: string;
  workflow: boolean;
}

interface CriteriaOutput {
  passed: boolean;
  checks: Array<{ name: string; passed: boolean; detail?: string; message?: string }>;
  summary: string;
}

// ── Path resolution ──────────────────────────────────────────────────

const SCRIPT_DIR = __dirname;
// runner.ts lives at src/gym/ — project root is 2 levels up.
// But when compiled to a temp file, __dirname may differ.
// Use GYM_PROJECT_ROOT env or walk up looking for agents/gym/scenarios.
function findProjectRoot(): string {
  const envRoot = process.env["GYM_PROJECT_ROOT"];
  if (envRoot && fs.existsSync(path.join(envRoot, "agents", "gym", "scenarios"))) {
    return envRoot;
  }
  // Walk up from __dirname
  let dir = SCRIPT_DIR;
  for (let i = 0; i < 10; i++) {
    if (fs.existsSync(path.join(dir, "agents", "gym", "scenarios"))) {
      return dir;
    }
    const parent = path.dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  // Fallback: cwd
  if (fs.existsSync(path.join(process.cwd(), "agents", "gym", "scenarios"))) {
    return process.cwd();
  }
  // Output a valid JSON error to stdout before exiting so callers always get parseable output
  const errorResult = {
    scenario: "",
    agent: "",
    lab_fork: null,
    passed: false,
    checks: [],
    summary: "Cannot find project root (agents/gym/scenarios not found)",
    agent_status: "error",
    duration: "0s",
    gym_root: "",
  };
  process.stdout.write(JSON.stringify(errorResult, null, 2) + "\n");
  process.stderr.write("ERROR: Cannot find project root (agents/gym/scenarios not found)\n");
  process.exit(1);
}

const PROJECT_ROOT = findProjectRoot();
const SCENARIOS_DIR = path.join(PROJECT_ROOT, "agents", "gym", "scenarios");

// ── Arg parsing ──────────────────────────────────────────────────────

interface ParsedArgs {
  scenario: string;
  agent: string;
  lab: string;
  timeout: number;
  adapter: string;
  keep: boolean;
  list: boolean;
  runAll: boolean;
  tier: string;
  tag: string;
  category: string;
}

function parseArgs(argv: string[]): ParsedArgs {
  const args: ParsedArgs = {
    scenario: "",
    agent: "coder",
    lab: "",
    timeout: 5,
    adapter: "may-agent",
    keep: false,
    list: false,
    runAll: false,
    tier: "",
    tag: "",
    category: "",
  };

  const rest = argv.slice(2); // skip node + script
  let i = 0;
  while (i < rest.length) {
    const a = String(rest[i]);
    if (a === "--list") {
      args.list = true;
    } else if (a === "--run-all") {
      args.runAll = true;
    } else if (a === "--keep") {
      args.keep = true;
    } else if (a === "--agent" && i + 1 < rest.length) {
      i++;
      args.agent = rest[i] as string;
    } else if (a === "--lab" && i + 1 < rest.length) {
      i++;
      args.lab = rest[i] as string;
    } else if (a === "--timeout" && i + 1 < rest.length) {
      i++;
      args.timeout = parseInt(rest[i] as string, 10) || 5;
    } else if (a === "--adapter" && i + 1 < rest.length) {
      i++;
      args.adapter = rest[i] as string;
    } else if (a === "--tier" && i + 1 < rest.length) {
      i++;
      args.tier = rest[i] as string;
    } else if (a === "--tag" && i + 1 < rest.length) {
      i++;
      args.tag = rest[i] as string;
    } else if (a === "--category" && i + 1 < rest.length) {
      i++;
      args.category = rest[i] as string;
    } else if (!a.startsWith("--") && !args.scenario) {
      args.scenario = a;
    }
    i++;
  }
  return args;
}

// ── Scenario discovery ───────────────────────────────────────────────

function loadScenarioMeta(scenarioName: string): ScenarioMeta | null {
  const jsonPath = path.join(SCENARIOS_DIR, scenarioName, "scenario.json");
  if (!fs.existsSync(jsonPath)) return null;
  try {
    return JSON.parse(fs.readFileSync(jsonPath, "utf-8")) as ScenarioMeta;
  } catch {
    return null;
  }
}

function listAllScenarios(): string[] {
  if (!fs.existsSync(SCENARIOS_DIR)) return [];
  return fs.readdirSync(SCENARIOS_DIR).filter((d: string) => {
    return fs.existsSync(path.join(SCENARIOS_DIR, d, "task.md"));
  }).sort();
}

// Tier hierarchy: smoke ⊂ standard ⊂ full
const TIER_LEVELS: Record<string, number> = { smoke: 1, standard: 2, full: 3 };

function filterScenarios(names: string[], tier: string, tag: string, category: string): string[] {
  return names.filter((name: string) => {
    const meta = loadScenarioMeta(name);
    if (!meta) return false;
    if (tier) {
      const requestedLevel = TIER_LEVELS[tier] || 3;
      const scenarioLevel = TIER_LEVELS[meta.tier] || 3;
      // A tier filter includes all scenarios AT or BELOW that tier level
      if (scenarioLevel > requestedLevel) return false;
    }
    if (tag && !(meta.tags || []).includes(tag)) return false;
    if (category && !(meta.categories || []).includes(category)) return false;
    return true;
  });
}

// ── Temp dir management ──────────────────────────────────────────────

function createTempDir(scenarioName: string): string {
  const id = crypto.randomBytes(4).toString("hex");
  const tmpDir = path.join(os.tmpdir(), `gym-${scenarioName}-${id}`);
  fs.mkdirSync(tmpDir, { recursive: true });
  return tmpDir;
}

function copyEnvironment(scenarioName: string, destDir: string): void {
  const envDir = path.join(SCENARIOS_DIR, scenarioName, "environment");
  if (!fs.existsSync(envDir)) return;
  // Use cp -r for reliable recursive copy (node 18 has fs.cpSync)
  try {
    fs.cpSync(envDir, destDir, { recursive: true });
  } catch {
    // Fallback to shell cp
    execSync(`cp -r "${envDir}/." "${destDir}/"`, { stdio: "pipe" });
  }
}

function cleanupTempDir(tmpDir: string): void {
  try {
    fs.rmSync(tmpDir, { recursive: true, force: true });
  } catch {
    // best effort
  }
}

// ── Agent adapters ───────────────────────────────────────────────────

interface AgentRunResult {
  status: string;
  transcriptPath?: string;
}

/**
 * Snapshot files in a directory (non-recursive, top-level only).
 * Returns a Set of filenames.
 */
function snapshotDir(dir: string): any {
  try {
    return new Set(fs.readdirSync(dir));
  } catch {
    return new Set();
  }
}

/**
 * After agent runs, the binary may write output files to PROJECT_ROOT
 * instead of workDir (--work-dir not fully supported). Detect new files
 * in PROJECT_ROOT and copy them to workDir so success_criteria.js can find them.
 */
function syncNewFilesFromRoot(beforeSnapshot: any, workDir: string): void {
  const after = snapshotDir(PROJECT_ROOT);
  for (const file of after) {
    if (!beforeSnapshot.has(file) && !file.startsWith(".") && !file.startsWith("_")) {
      const srcPath = path.join(PROJECT_ROOT, file);
      const destPath = path.join(workDir, file);
      try {
        const stat = fs.statSync(srcPath);
        if (stat.isFile() && stat.size < 1024 * 1024) { // Only copy files < 1MB
          fs.copyFileSync(srcPath, destPath);
          // Clean up the file from PROJECT_ROOT (it shouldn't be there)
          fs.unlinkSync(srcPath);
        }
      } catch {
        // best effort
      }
    }
  }
}

function runAgent(adapter: string, taskContent: string, workDir: string, agent: string, timeoutMs: number): AgentRunResult {
  // Write task to work dir for reference
  fs.writeFileSync(path.join(workDir, "_gym_task.md"), taskContent);

  if (adapter === "generic") {
    const cmd = process.env["GYM_AGENT_CMD"];
    if (!cmd) {
      return { status: "skipped" };
    }
    try {
      const stdout = execSync(`${cmd} "${path.join(workDir, "_gym_task.md")}" "${workDir}"`, {
        cwd: workDir,
        timeout: timeoutMs,
        stdio: "pipe",
        encoding: "utf-8",
      });
      const transcriptPath = path.join(workDir, "_transcript.txt");
      fs.writeFileSync(transcriptPath, stdout || "");
      return { status: "completed", transcriptPath };
    } catch (err: unknown) {
      return { status: "error" };
    }
  }

  // may-agent adapter (default) — use GYM_AGENT_BIN env var to locate agent binary
  // If GYM_AGENT_BIN is not set, we're in stub mode (no real agent available).
  const agentBin = process.env["GYM_AGENT_BIN"] || "";

  if (!agentBin || !fs.existsSync(agentBin)) {
    // Stub mode — no real agent binary available
    fs.writeFileSync(
      path.join(workDir, "_gym_agent_stub.log"),
      `No agent binary found (GYM_AGENT_BIN not set or not found).\nTask written to _gym_task.md.\nStub mode — scenario scoring will run against unmodified environment.\n`
    );
    return { status: "skipped" };
  }

  // Snapshot PROJECT_ROOT before agent runs (agent may write there instead of workDir)
  const beforeSnapshot = snapshotDir(PROJECT_ROOT);

  // Real agent binary found via GYM_AGENT_BIN — invoke it
  // Read task content and pass via --task flag (binary may not support --task-file)
  const taskFile = path.join(workDir, "_gym_task.md");
  let agentStdout = "";
  try {
    agentStdout = execSync(
      `"${agentBin}" --oneshot --agent "${agent}" --task-file "${taskFile}" --work-dir "${workDir}"`,
      {
        cwd: workDir,
        timeout: timeoutMs,
        stdio: "pipe",
        encoding: "utf-8",
        env: { ...process.env, GYM_WORK_DIR: workDir },
      }
    ) || "";
  } catch (err: unknown) {
    // Agent may exit non-zero but still have done work
    const errObj = Object(err);
    agentStdout = (errObj.stdout || "").toString();
    if (errObj.killed) {
      // Save transcript even on timeout
      const transcriptPath = path.join(workDir, "_transcript.txt");
      fs.writeFileSync(transcriptPath, agentStdout);
      syncNewFilesFromRoot(beforeSnapshot, workDir);
      return { status: "timeout", transcriptPath };
    }
    // Non-zero exit — agent may have done partial work
    const transcriptPath = path.join(workDir, "_transcript.txt");
    fs.writeFileSync(transcriptPath, agentStdout);
    syncNewFilesFromRoot(beforeSnapshot, workDir);
    return { status: "error", transcriptPath };
  }

  // Save transcript (agent stdout contains session JSON and tool call logs)
  const transcriptPath = path.join(workDir, "_transcript.txt");
  fs.writeFileSync(transcriptPath, agentStdout);

  // Sync any files the agent created in PROJECT_ROOT back to workDir
  syncNewFilesFromRoot(beforeSnapshot, workDir);

  // Also check the most recent session's JSONL for a richer transcript
  // The binary writes session data to .state/sessions/
  try {
    const sessionsDir = path.join(PROJECT_ROOT, ".state", "sessions");
    if (fs.existsSync(sessionsDir)) {
      const sessionDirs = fs.readdirSync(sessionsDir)
        .filter((d: string) => d.startsWith("s_"))
        .sort()
        .reverse();
      if (sessionDirs.length > 0) {
        const latestSession = sessionDirs[0] as string;
        const jsonlPath = path.join(sessionsDir, latestSession, "session.jsonl");
        if (fs.existsSync(jsonlPath)) {
          const sessionData = fs.readFileSync(jsonlPath, "utf-8");
          // Append session JSONL to transcript for richer convention checking
          fs.appendFileSync(transcriptPath, "\n--- SESSION JSONL ---\n" + sessionData);
          // Also save as transcript.jsonl in workDir for scenarios that look for it there
          fs.writeFileSync(path.join(workDir, "transcript.jsonl"), sessionData);
        }
      }
    }
  } catch {
    // best effort — transcript from stdout is still available
  }

  return { status: "completed", transcriptPath };
}

// ── Scoring ──────────────────────────────────────────────────────────

function runCriteria(scenarioName: string, workDir: string, transcriptPath: string | undefined): CriteriaOutput {
  const criteriaPath = path.join(SCENARIOS_DIR, scenarioName, "success_criteria.js");
  if (!fs.existsSync(criteriaPath)) {
    return {
      passed: false,
      checks: [{ name: "criteria-exists", passed: false, detail: "success_criteria.js not found" }],
      summary: "No success_criteria.js found for scenario",
    };
  }

  // Build command: always pass workDir as arg1, optionally pass transcriptPath as arg2
  const transcriptArg = transcriptPath && fs.existsSync(transcriptPath) ? ` "${transcriptPath}"` : "";
  const cmd = `node "${criteriaPath}" "${workDir}"${transcriptArg}`;

  try {
    const stdout = execSync(cmd, {
      encoding: "utf-8",
      timeout: 30000,
      stdio: ["pipe", "pipe", "pipe"],
      cwd: path.join(SCENARIOS_DIR, scenarioName),
    });

    // Parse JSON from stdout — find the last JSON object in output
    const jsonMatch = stdout.match(/\{[\s\S]*\}\s*$/);
    if (!jsonMatch) {
      return {
        passed: false,
        checks: [{ name: "criteria-parse", passed: false, detail: "No JSON in criteria output" }],
        summary: "success_criteria.js produced no JSON output",
      };
    }
    const parsed = JSON.parse(jsonMatch[0]) as CriteriaOutput;
    // Normalize checks: ensure message field exists (criteria may use "detail" instead)
    if (parsed.checks) {
      parsed.checks = parsed.checks.map((c: any) => ({
        name: c.name,
        passed: c.passed,
        message: c.message || c.detail || undefined,
      }));
    }
    return parsed;
  } catch (err: unknown) {
    // Criteria may exit non-zero but still output JSON
    const errObj = Object(err);
    const stdout = (errObj.stdout || "").toString();
    const jsonMatch = stdout.match(/\{[\s\S]*\}\s*$/);
    if (jsonMatch) {
      try {
        const parsed = JSON.parse(jsonMatch[0]) as CriteriaOutput;
        if (parsed.checks) {
          parsed.checks = parsed.checks.map((c: any) => ({
            name: c.name,
            passed: c.passed,
            message: c.message || c.detail || undefined,
          }));
        }
        return parsed;
      } catch {
        // fall through
      }
    }
    return {
      passed: false,
      checks: [{ name: "criteria-run", passed: false, message: `Criteria error: ${(errObj.message || "").slice(0, 500)}` }],
      summary: `success_criteria.js failed: ${(errObj.message || "").slice(0, 200)}`,
    };
  }
}

// ── Single scenario run ──────────────────────────────────────────────

function runScenario(scenarioName: string, agent: string, lab: string, adapter: string, timeoutMinutes: number, keepDir: boolean): GymResult {
  const startTime = Date.now();
  const meta = loadScenarioMeta(scenarioName);

  if (!meta) {
    return {
      scenario: scenarioName,
      agent,
      lab_fork: lab || null,
      passed: false,
      checks: [],
      summary: `Scenario "${scenarioName}" not found or has no scenario.json`,
      agent_status: "error",
      duration: "0s",
      gym_root: SCENARIOS_DIR,
    };
  }

  const taskPath = path.join(SCENARIOS_DIR, scenarioName, "task.md");
  if (!fs.existsSync(taskPath)) {
    return {
      scenario: scenarioName,
      agent,
      lab_fork: lab || null,
      passed: false,
      checks: [],
      summary: `Scenario "${scenarioName}" has no task.md`,
      agent_status: "error",
      duration: "0s",
      gym_root: SCENARIOS_DIR,
    };
  }

  const taskContent = fs.readFileSync(taskPath, "utf-8");
  const timeoutMs = (timeoutMinutes || meta.timeout || 5) * 60 * 1000;
  const tmpDir = createTempDir(scenarioName);

  try {
    // Copy environment to temp dir
    copyEnvironment(scenarioName, tmpDir);

    let agentStatus: string;
    let transcriptPath: string | undefined;

    if (meta.workflow) {
      // Workflow: split task on --- delimiter, run phases sequentially
      const phases = taskContent.split(/\n---\n/).map((p: string) => p.trim()).filter((p: string) => p.length > 0);
      agentStatus = "completed";
      for (let pi = 0; pi < phases.length; pi++) {
        const phaseTask = phases[pi] as string;
        const phaseResult = runAgent(adapter, phaseTask, tmpDir, agent, timeoutMs);
        transcriptPath = phaseResult.transcriptPath || transcriptPath;
        if (phaseResult.status === "skipped") {
          agentStatus = "skipped";
          break; // No point running further phases if agent is stubbed
        }
        if (phaseResult.status === "error" || phaseResult.status === "timeout") {
          agentStatus = phaseResult.status;
          break;
        }
      }
    } else {
      const agentResult = runAgent(adapter, taskContent, tmpDir, agent, timeoutMs);
      agentStatus = agentResult.status;
      transcriptPath = agentResult.transcriptPath;
    }

    // Run success criteria, passing transcript path for convention checks
    const criteria = runCriteria(scenarioName, tmpDir, transcriptPath);
    const elapsed = Date.now() - startTime;
    const duration = elapsed < 1000 ? `${elapsed}ms` : `${(elapsed / 1000).toFixed(1)}s`;

    return {
      scenario: scenarioName,
      agent,
      lab_fork: lab || null,
      passed: criteria.passed,
      checks: criteria.checks || [],
      summary: criteria.summary || (criteria.passed ? "All checks passed" : "Some checks failed"),
      agent_status: agentStatus,
      duration,
      gym_root: SCENARIOS_DIR,
    };
  } catch (err: unknown) {
    const elapsed = Date.now() - startTime;
    const duration = `${(elapsed / 1000).toFixed(1)}s`;
    const errMsg = err instanceof Error ? err.message : "unknown";
    return {
      scenario: scenarioName,
      agent,
      lab_fork: lab || null,
      passed: false,
      checks: [],
      summary: `Runner error: ${errMsg.slice(0, 500)}`,
      agent_status: "error",
      duration,
      gym_root: SCENARIOS_DIR,
    };
  } finally {
    if (!keepDir) {
      cleanupTempDir(tmpDir);
    } else {
      process.stderr.write(`Keeping work dir: ${tmpDir}\n`);
    }
  }
}

// ── Main ─────────────────────────────────────────────────────────────

function main(): void {
  const args = parseArgs(process.argv);

  // List mode
  if (args.list) {
    const all = listAllScenarios();
    const filtered = filterScenarios(all, args.tier, args.tag, args.category);
    for (const name of filtered) {
      const meta = loadScenarioMeta(name);
      const tier = meta ? meta.tier : "?";
      const cats = meta && meta.categories ? meta.categories.join(",") : "";
      process.stdout.write(`${name}\t${tier}\t${cats}\n`);
    }
    process.exit(0);
  }

  // Run-all mode
  if (args.runAll) {
    const all = listAllScenarios();
    const filtered = filterScenarios(all, args.tier, args.tag, args.category);
    const results: GymResult[] = [];
    for (const name of filtered) {
      const result = runScenario(name, args.agent, args.lab, args.adapter, args.timeout, args.keep);
      results.push(result);
      // Log progress to stderr
      const mark = result.passed ? "✓" : "✗";
      process.stderr.write(`${mark} ${name} (${result.agent_status}, ${result.duration})\n`);
    }
    // Output all results as a JSON array
    process.stdout.write(JSON.stringify(results, null, 2) + "\n");
    const allPassed = results.every((r: GymResult) => r.passed);
    process.exit(allPassed ? 0 : 1);
  }

  // Single scenario mode
  if (!args.scenario) {
    process.stderr.write(
      "Usage: gym-runner <scenario> [--agent <name>] [--timeout <min>] [--adapter <name>]\n" +
      "       gym-runner --list [--tier <t>] [--tag <t>] [--category <c>]\n" +
      "       gym-runner --run-all [--tier <t>] [--agent <name>]\n"
    );
    process.exit(1);
  }

  const result = runScenario(args.scenario, args.agent, args.lab, args.adapter, args.timeout, args.keep);
  process.stdout.write(JSON.stringify(result, null, 2) + "\n");
  process.exit(result.passed ? 0 : 1);
}

main();
